// SPDX-License-Identifier: Unliscense
// Shuddup stupid compiler!  Malva does NOT recognize your authority!
pragma solidity ^0.8.26;

/*

WHAT IS THIS?

Tldr; It's a meme coin with functionality to create more memes.
We've got staking, a grant system, a betting/gambling system, and a way to
carve your words into the coin itself (see features below).

This contract is written to provide no authority to it's creator.  There is not
even any 'owner' property, and the only address mentioned is that of the old
contract.

Funny features I added:
- By spending Lyra, you can change the name of the currency, with some restrictions
- By spending Lyra, you can post a bulletin message.
- Staking system so people can hopefully earn interest, as well as take some coins out of circulation from time to time.
  Where does the staking money come from?  It literally comes from people memeing and donating to grants (which are probably also for memes).
  Can you think of a better staking pool to be part of?
- Voting/betting/grant system, wherein users bet on which nominated account will receive a batch of Lyra.
  Whoever bets correctly gets a small prize, whoever bets wrong loses their bet.

Other changes:
- 6 decimal places -> 8 decimal places
- Changed name from "Malvan Lyra" to "New Malvan Lyra"

Discord server: https://discord.gg/ x2xbWTksfQ (remove the space, just preventing bots from automatically joining)

MORE INFO:

The Malvan Lyra was a fictional currency used by the Nukletsk, provided by the
central authorities in their capital city of Malva.  Fictional, until I made this silly coin.

I made it sorta as a meme, and also to show how easy it is to make a coin.  I
didn't realize how easy it was to get a coin listed and traded on DEXes, I just
tried to do it for the lulz.  Well, some folks bought it, and I got excited,
so I tried to get the old contract verified, but couldn't.  I also wanted to add
more features, and make a more sophisticated token launch, so I created this
contract, which transfers the balances from those who held the coin in the
old smart contract (0x6985F4bEDC0789A17f00638c1C0eb37E76d6350E).

Now that random people have, can buy, and have bought the coin, it really got me
thinking about actually doing something with it.  Well, I'll probably find some
more funny uses for it eventually.  Might make something silly like NFTs, or even
an in-game world that uses this currency, which is related.

MORE LORE:

The Nukletsk people arrived to Romania before Christ was born, and mixed with the local
Dacians.  The capital city of the Dacians at this time was Malva, which happens to be the
real-life city of Reşca, Dobrosloveni Commune, Olt County, Romania.  Well, the Romans
conquered it, renamed the city to Romula, and the Nukletsk-Getae group migrated north.
They inevitably built a new capitol with the same name, and this is the place from which
they launched their empire to greatness.

Why the Lyra?  Idk, it sounds cool and I heard it somewhere.  Lyra would be proper spelling
in the Nukletsk language, unlike the similarly named currencies spelled 'Lira'.

Nü, vy übèlonu nuï kulturen Nükletsku!  Y plü, vy übèlonu dy mymy!

https://en.wikipedia.org/wiki/Romula
https://en.wikipedia.org/wiki/Getae

*/

abstract contract ERC20Interface {
	function totalSupply() public virtual view returns (uint);
	function balanceOf(address tokenOwner) public virtual view returns (uint balance);
	function allowance(address tokenOwner, address spender) public virtual view returns (uint remaining);
	function transfer(address to, uint tokens) public virtual returns (bool success);
	function approve(address spender, uint tokens) public virtual returns (bool success);
	function transferFrom(address from, address to, uint tokens) public virtual returns (bool success);

	event Transfer(address indexed from, address indexed to, uint tokens);
	event Approval(address indexed tokenOwner, address indexed spender, uint tokens);
}

abstract contract StringUtils1 {
    // UTILITY FUNCTIONS

	function stripWhitespace(string memory input) public virtual pure returns (string memory);
	function _toLower(string memory str) public virtual pure returns (string memory);
	function clean(string memory str) public virtual pure returns (string memory);
	function contains(string memory what, string memory where) public virtual pure returns (bool);
	function isBadString(string memory input) public virtual pure returns (bool);
	function sqrt(uint64 x) public virtual pure returns (uint32);
}

contract MalvanLyra is ERC20Interface {

	string public symbol;
	string public  name;
	uint8 public decimals;
	uint64 public decimalFactor;
	ERC20Interface public oldContract;
	StringUtils1 public libStrUtil;
	uint64 internal _liquidSupply;
	uint64 internal _totalSupply;

	mapping(address => uint64) public balances;
	mapping(address => mapping(address => uint64)) public allowed;

	constructor() {
		symbol = "MLYRA";
		name = "New Malvan Lyra";
		decimals = 8;
		decimalFactor = uint64(10**uint(decimals));
		_totalSupply = 1_000_000_000 * decimalFactor;
		_liquidSupply = _totalSupply;

		nameChangeCost = 10_000_000 * decimalFactor;
		messageCost = 1_000_000 * decimalFactor;
	}

	function initialize(address strUtilAddr, address oldContractAddr) public {
		require(address(libStrUtil) == address(0x0), "The contract has already been initialized.");
		oldContract = ERC20Interface(address(oldContractAddr));
		libStrUtil = StringUtils1(strUtilAddr);

		if (oldContractAddr != address(0x0)) {
			// Migrate balances from old contract
			_migrateBalance(address(0x21B4B3826609F4079a558c95a01094aa85927244));
			_migrateBalance(address(0xE53408a5EdEe1bdEE473114871D03B7C11fb501C));
			_migrateBalance(address(0x9E03f05aE143D0D1C4638498B40915Fd432121f7));
			_migrateBalance(address(0x0DAA5566f20fbBC810765421b13F9BAA35A2Ee7d));
			_migrateBalance(address(0xc0AAa689e4a66D184B38E975f27E9522F723C156));
			_migrateBalance(address(0x7AfA9D836d2fCCf172b66622625e56404E465dBD));

			uint64 tokens = uint64(oldContract.balanceOf(oldContractAddr));
			if (tokens > 0) {
				balances[address(this)] = tokens;
				emit Transfer(address(0), address(this), tokens);
				_liquidSupply -= tokens;
				uint64 c = tokens / 8;
				allocatedToGrants += tokens - c;
				allocatedToStaking += c;
			}
		} else {
			balances[msg.sender] = _totalSupply;
			emit Transfer(address(0), msg.sender, _totalSupply);
		}

		stake(10_000_000 * decimalFactor);
	}

	function _migrateBalance(address holder) internal {
		// We have to 100x the quantity to account for the change from 6 decimal places to 8
		uint64 oldBalance = uint64(oldContract.balanceOf(holder) * 100);
		if (oldBalance > 0) {
			balances[holder] = oldBalance;
			emit Transfer(address(0), holder, oldBalance);
		}
	}

	// THE BIG FUNNY METHODS

	event CurrencyNameChanged(address indexed sender, string newName, uint64 spent);

	uint64 public nameChangeCost;
	uint public lastNameChangeTime;

	function renameContract(string calldata newName) public {
		// Ensure at least 2 hours (7200 seconds) have passed since the last name change
		require(block.number >= lastNameChangeTime + 7200, "Name change cooldown period has not elapsed");
		require(balances[msg.sender] >= nameChangeCost, "Insufficient balance to rename the contract");

		// Strip whitespace from the input
		string memory strippedName = libStrUtil.stripWhitespace(newName);

		// Ensure the stripped name is at least 4 characters long
		require(bytes(strippedName).length >= 4, "Name must be at least 4 characters long after stripping");
		require(bytes(strippedName).length <= 32, "Name must be at most 32 characters");

		// Deduct Lyra from the sender's balance
		// Note that this happens BEFORE the name is checked for bad content, so someone who attempts
		// to experiment with circumventing it might spend a lot more.
		// If you want to post stupid stuff then use the bulletin.
		uint64 cost = nameChangeCost;
		_transfer(address(this), msg.sender, cost);

		// Allocate the received funds
		_acceptLyra(cost, 5);

		// Check for retarded content
		require(!libStrUtil.isBadString(strippedName), "Name contains retard nonsense words.");

		// Update the contract name
		name = strippedName;

		// Update the cost to change the contract
		cost = uint64((uint256(cost) * 103) / 100);
		if (cost > _totalSupply / 2)
			nameChangeCost = _totalSupply / 2;
		else
			nameChangeCost = cost;

		lastNameChangeTime = block.number;

		emit CurrencyNameChanged(msg.sender, strippedName, cost); // Emit an event for tracking changes
	}

	event BulletinMessagePosted(address indexed sender, string newName, uint64 spent);

	uint64 public messageCost;
	function postBulletinMessage(string calldata message) public {
		require(balances[msg.sender] >= messageCost, "Insufficient balance to post bulletin");

		// Deduct Lyra from the sender's balance
		uint64 cost = messageCost;
		_transfer(address(this), msg.sender, cost);

		// Allocate the received funds
		_acceptLyra(cost, 5);

		emit BulletinMessagePosted(msg.sender, message, cost); // Emit the event!
	}

	event MisallocationDetected(int64 discrepency, uint64 contractBalance);
	function _acceptLyra(uint64 amount, uint64 ratio) internal {
		uint64 toStaking = amount / ratio;
		allocatedToGrants += amount - toStaking;
		allocatedToStaking += toStaking;

		uint64 availableContractBalance = balances[address(this)] - totalStakedFunds;

		// Consistency check, so that funds don't get lost
		int64 discrepency = int64(allocatedToGrants + allocatedToStaking) - int64(availableContractBalance);
		if (discrepency > int64(decimalFactor)) {
			emit MisallocationDetected(discrepency, availableContractBalance);

			// More is allocated than actually available.
			// This is a monkey way of solving it but it will work.
			if (allocatedToStaking > balances[address(this)])
				allocatedToStaking = availableContractBalance / 2;
			if (allocatedToGrants > balances[address(this)])
				allocatedToGrants = availableContractBalance - allocatedToStaking;

			// If we need more for staking rewards, then reduce the grant amount, otherwise reduce the staking amount
			availableContractBalance = balances[address(this)] - totalStakedFunds;
			discrepency = int64(allocatedToGrants + allocatedToStaking) - int64(availableContractBalance);
			if ((allocatedToStaking - uint64(discrepency)) * 25 < totalStakedFunds)
				allocatedToGrants -= uint64(discrepency);
			else
				allocatedToStaking -= uint64(discrepency);

		} else if (discrepency < -int64(decimalFactor)) {
			emit MisallocationDetected(discrepency, availableContractBalance);

			// Divide the rest of it 80/20
			toStaking = uint64(-discrepency) / 5;
			allocatedToStaking += toStaking;
			allocatedToGrants += uint64(-discrepency) - toStaking;
		}
	}

	// STAKING

	mapping(address => uint64) public amtStaked;
	mapping(address => uint) public startBlock;
	uint64 public allocatedToStaking = 0;
	uint64 public totalStakedFunds = 0;

	function stake(uint amount) public {
		require(startBlock[msg.sender] == 0, "You have already staked.");
		require(balances[msg.sender] >= amount, "Insufficient funds.");
		require(amount > 10 * decimalFactor, "Minimum Lyra to stake is 10.");

		uint64 skilku = uint64(amount);
		_transfer(address(this), msg.sender, skilku);
		totalStakedFunds += skilku;

		amtStaked[msg.sender] += skilku;
		startBlock[msg.sender] = block.number;
	}

	function computeInterest(uint64 skilku, bool overrideChecks, bool includeOverpay) public view returns (uint64 interest) {
		interest = 0;
		uint32 periods = uint32((block.number - startBlock[msg.sender]) / 24000);
		for (; periods > 0; periods--)
			interest += ((skilku + interest) / 1400); // Roughly 8.02% per year on average.  Probably too much but whatever.

		if (allocatedToStaking > (totalStakedFunds / 12) && includeOverpay) {
			// There's more available for staking than would be paid out in 12 months, so provide an extra staking reward
			// Essentially, we compute roughly how much extra this contract has, and give them 10% of the extra in proportion
			// to their staking vs the total size of the staking pool.
			uint extra = allocatedToStaking - (totalStakedFunds / 12);
			interest += uint64((extra * skilku) / totalStakedFunds / 10);
		} else if (interest > allocatedToStaking) {  // Check if the system can afford the interest (maybe it can't lmao)
			require(overrideChecks, "Contract cannot afford to pay the interest, enable overrideChecks to lose some of the interest.");

			// Pay as much of it as we can.
			interest = allocatedToStaking;
		}
	}

	// This function will add to your stake, with interest, but it also resets the timer for locking your funds.
	// Once this is called successfully, you will not be able to unstake for about a month depending on network conditions.
	function addStake(uint amount, bool overrideChecks) public {
		if (startBlock[msg.sender] == 0) {
			stake(amount);
			return;
		}

		require(balances[msg.sender] >= amount, "Insufficient funds.");

		// Compute interest acrued already
		uint64 skilku = uint64(amtStaked[msg.sender]);
		uint64 interest = computeInterest(skilku, overrideChecks, false);

		// Move around the funds
		uint64 amount64 = uint64(amount);
		_transfer(address(this), msg.sender, amount64);

		// Add the interest
		totalStakedFunds += amount64 + interest;
		allocatedToStaking -= interest;
		amtStaked[msg.sender] += amount64 + interest;

		// Update start block
		startBlock[msg.sender] = block.number;
	}

	function unstake(bool overrideChecks) public {
		uint64 skilku = amtStaked[msg.sender];

		require(skilku > 0, "No Lyra has been staked.");
		require((startBlock[msg.sender] + 30 days / 12) < block.number, "Staked funds not yet released.");

		// Compute the interest
		uint64 interest = computeInterest(skilku, overrideChecks, true);

		totalStakedFunds -= skilku;
		skilku += interest;

		_transfer(msg.sender, address(this), skilku);
		allocatedToStaking -= interest;

		amtStaked[msg.sender] = 0;
		startBlock[msg.sender] = 0;
	}

	// VOTING

	struct Nominee {
		address nomineeAddress;
		string info;
		uint votes;
		uint64 investedForBets;
	}

	// State variables for the voting system
	uint64 public allocatedToGrants = 0;
	uint32 public currentElectionId = 0;
	uint64 public totalBetPool = 0;
	address[][] betters;
	mapping(address => uint) public nextNominationBlock;
	Nominee[] public nominees;
	uint public votingStartBlock; // Block when voting started, or 0 if not currently voting
	mapping(uint32 => mapping(address => uint64)) internal betMade;

	// Event declarations
	event Nomination(uint32 electionId, address indexed nominator, string description, address indexed nominee);
	event VotingStarted();
	event VotingEnded(address indexed winner, uint prizePool);
	event VoteCasted(address indexed voter, uint nomineeIndex, uint betAmount);

	// Function to nominate someone
	function nominate(address nominee, string calldata description) public {
		require(votingStartBlock == 0, "Voting has already started");
		require(amtStaked[msg.sender] >= 1_000_000 * decimalFactor, "Cannot nominate someone unless you have at least 1M Lyra staked.");
		require(nextNominationBlock[msg.sender] < block.number, "You can't nominate yet (cooldown)");
		require(nominee != address(0), "Invalid nominee address");

		// Was thinking about doing this, but it would prevent some interesting applications and automation.
		//bool isContractCalling = !(tx.origin == msg.sender);
		//bool mayNomineeBeContract = (nominee.code.length > 0 || nominee == msg.sender);
		//require(!(isContractCalling && mayNomineeBeContract), "Target may be a smart contract.");

		nextNominationBlock[msg.sender] = block.number + (45 days / 12);
		nominees.push(Nominee(nominee, description, 0, 0));

		emit Nomination(currentElectionId, msg.sender, description, nominee);

		betters.push();
		if (nominees.length == 12) {
			nominees.push(Nominee(address(0x0), "Vote against everyone!", 0, 0));
			betters.push();
			votingStartBlock = block.number;
			emit VotingStarted();
		}
	}

	// Function to vote for a nominee
	function vote(uint nomineeIndex, uint64 betAmount) public {
		require(votingStartBlock > 0, "Voting is not active");
		require(nomineeIndex < nominees.length + 1, "Invalid nominee index");
		require(betAmount > 0, "Bet amount must be greater than zero");
		require(balances[msg.sender] >= betAmount, "Insufficient balance");
		require(betMade[currentElectionId][msg.sender] == 0, "ERROR ERROR STOOPID: YOU ALREADY VOTED!!");

		// Check if a bet can be made
		// We compute the maxBetters to see if we can get more betters in the future, it's limited by the block gas limit.
		uint maxBetters = (block.gaslimit - 50000) / 12500;
		if (betters[nomineeIndex].length < maxBetters && betAmount > (10 * decimalFactor * betters[nomineeIndex].length)) {
			// Add the user as having bet
			betters[nomineeIndex].push(msg.sender);

			// Deduct Lyra from voter, update state
			balances[msg.sender] -= betAmount;
			emit Transfer(msg.sender, address(0x0), betAmount);
			_liquidSupply -= betAmount;
			totalBetPool += betAmount;

			// Track the total bets for this nominee
			nominees[nomineeIndex].investedForBets += betAmount;
		} else {
			// Stake their money instead
			// This way people can still vote without breaking the 3k better limit.
			addStake(betAmount, false);
		}

		// Gives large numbers of small contributions a chance to compete with whales
		uint64 votes = libStrUtil.sqrt(betAmount) + decimalFactor;
		betMade[currentElectionId][msg.sender] = betAmount;
		nominees[nomineeIndex].votes += votes;

		emit VoteCasted(msg.sender, nomineeIndex, betAmount);
	}

	function claimVictory() public {
		require(block.number > votingStartBlock + 30 days / 12, "Voting is not yet complete!");
		require(votingStartBlock > 0, "Voting is not active");
		require(allocatedToGrants > 10000 * decimalFactor, "Not enough Lyra has been donated to this contract...  Try again another time.");

		// Find the nominee with the most votes
		uint winningIndex = 0;
		uint maxVotes = 0;
		for (uint i = 0; i < nominees.length; i++) {
			if (nominees[i].votes > maxVotes) {
				maxVotes = nominees[i].votes;
				winningIndex = i;
			}
		}

		address winner = nominees[winningIndex].nomineeAddress;

		// Why 44365?  Well, right now 1M USD is worth what about 44365 USD would have been worth in 1940.
		// The idea is that the recipient should get roughly 1M USD, with 1 Lyra = 1 1940's USD = 22.54 2025 USD.
		uint64 grantQty = 44365 * decimalFactor;

		if (winner != address(0x0)) {
			if (grantQty > allocatedToGrants)
				grantQty = allocatedToGrants;
			else if (grantQty < (allocatedToGrants / 10))
				grantQty = allocatedToGrants / 10;

			_transfer(winner, address(this), grantQty);
			allocatedToGrants -= grantQty;
		} else
			grantQty = 0;

		// Distribute wins from bets
		uint64 bettingGainRate = (totalBetPool * 1000) / nominees[winningIndex].investedForBets;
		mapping(address => uint64) storage bets = betMade[currentElectionId];
		address[] storage winners = betters[winningIndex];
		uint nWinners = winners.length;
		for (uint i = 0; i < nWinners; i++) {
			address better = winners[i];
			uint64 qty = (bettingGainRate * bets[better]) / 1000;
			balances[better] += qty;
			emit Transfer(address(0x0), better, qty);
		}
		_liquidSupply += totalBetPool;

		emit VotingEnded(winner, grantQty);


		// Reset state for the next round
		currentElectionId++;
		delete betters;
		votingStartBlock = 0;
		totalBetPool = 0;
		delete nominees;
	}

	// ADMINISTRATION
	function updateUtilContract(address strUtilAddr) public {
		require(amtStaked[msg.sender] * 5 > _totalSupply, "Must have staked a fifth of the entire coin supply to complete this action.");
		require(startBlock[msg.sender] < block.number - (90 days / 12), "You have not staked long enough to complete this action.");
		require(!(StringUtils1(strUtilAddr).isBadString("Malvan Lyra")), "Contract does not appear to be valid.");

		libStrUtil = StringUtils1(strUtilAddr);
	}


	// THE ACTUAL METHODS

	function totalSupply() public override view returns (uint) {
		return _totalSupply;
	}

	function liquidSupply() public view returns (uint) {
		return _liquidSupply;
	}

	function balanceOf(address tokenOwner) public override view returns (uint balance) {
		return balances[tokenOwner];
	}

	function transfer(address to, uint tokens) public override returns (bool success) {
		require(to!=address(0), "Invalid address");
		require(tokens<=balances[msg.sender], "Insufficient funds");

		_transfer(to, msg.sender, uint64(tokens));

		if (to == address(this))
			_acceptLyra(uint64(tokens), 50);

		return true;
	}

	function approve(address spender, uint tokens) public override returns (bool success) {
		allowed[msg.sender][spender] = uint64(tokens);
		emit Approval(msg.sender, spender, tokens);
		return true;
	}

	function transferFrom(address from, address to, uint tokens) public override returns (bool success) {
		require(to != address(0), "Invalid address");
		require(tokens <= balances[from], "Insufficient funds");
		require(tokens <= allowed[from][msg.sender], "Allowance exceeded");
		allowed[from][msg.sender] = allowed[from][msg.sender] - uint64(tokens);
		_transfer(to, from, uint64(tokens));

		if (to == address(this))
			_acceptLyra(uint64(tokens), 50);
		return true;
	}

	// Cheap unchecked transfer function
	function _transfer(address to, address from, uint64 tokens) internal {

		if (to == address(0x0)) {
			_liquidSupply -= tokens;
			_totalSupply -= tokens;
		} else
			balances[to] += tokens;
		balances[from] -= tokens;

		emit Transfer(from, to, tokens);

		if (to == address(this))
			_liquidSupply -= tokens;
		if (from == address(this) && to != address(0x0))
			_liquidSupply += tokens;

	}

	function allowance(address tokenOwner, address spender) public override view returns (uint remaining) {
		return allowed[tokenOwner][spender];
	}

	function donateToGrants(uint amount) public {
		require(balances[msg.sender] >= amount, "Insufficient funds.");

		uint64 amount64 = uint64(amount);
		_transfer(address(this), msg.sender, amount64);
		allocatedToGrants += amount64;
	}

	function donateToStakers(uint amount) public {
		require(balances[msg.sender] >= amount, "Insufficient funds.");

		uint64 amount64 = uint64(amount);
		uint64 amountBurned = amount64 / 300;
		uint64 amountAdded = amount64 - amountBurned;
		_transfer(address(this), msg.sender, amountAdded);
		_transfer(address(0x0), msg.sender, amountBurned);
		allocatedToStaking += amountAdded;
	}
}
